export { RELIC_TEMPLATES }

/**
 * Total Lab Speed bonus, as a percent, from the relics a player owns.
 *
 * A "Relic Discount %" that is read but never derived sits at 0 no matter how
 * many Lab Speed relics the player has collected, and
 * `calculateLabsProgressModifiers` folds it into every time and cost — so the
 * whole lab view is quietly priced as though the player owned no relics.
 *
 * Accepts a relic `tracked` map, whose entries are `{ id, collected }`, and
 * tolerates a plain boolean map.
 */
export function computeLabSpeedRelicBonusPercent(
  tracked: Record<string, { collected?: boolean } | boolean> | null | undefined,
): number {
  if (!tracked || typeof tracked !== 'object') return 0
  let total = 0
  for (const template of RELIC_TEMPLATES) {
    if (template.bonusType !== 'Lab Speed') continue
    const entry = tracked[template.id]
    const owned = typeof entry === 'boolean' ? entry : entry?.collected === true
    if (!owned) continue
    const percent = Number.parseFloat(String(template.value ?? '').replace('%', ''))
    if (Number.isFinite(percent)) total += percent
  }
  // Round to two decimals: summing values like 1.5 and 2 in binary floating
  // point otherwise surfaces as 3.5000000000000004 in the input.
  return Math.round(total * 100) / 100
}

/* -------------------------------------------------------------------------- *
 * How relics are unlocked, and the published all-relics totals.
 *
 * Game facts, not presentation. Prose describing what relics are *for* lives in
 * `thetowersdk/knowledge`.
 * -------------------------------------------------------------------------- */

function buildRelicBonusCategory(
  key: RelicBonusCategoryKey,
  label: string,
  description: string,
  rows: readonly RelicBonusTotalRow[],
): RelicBonusCategoryDefinition {
  return { key, label, description, rows }
}

